import {calendarCells,calendarEntry,conferenceType,conferencePaper,CONFERENCE_START,CONFERENCE_END} from './morning-opening.js';
const esc=v=>String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function calendarHTML(o,{year,month,selected=null,nowLabel='07:20'}){
 const entry=selected?calendarEntry(o,selected):null,isToday=selected===o.today;
 const days=calendarCells(year,month).map(d=>{const type=calendarEntry(o,d.date),today=d.date===o.today;return`<button class="calendar-cell ${!d.inMonth?'muted':''} ${today?'today':''} ${selected===d.date?'selected':''}" data-calendar-date="${d.date}" aria-label="${d.date}${today?'，今天':''}" aria-pressed="${selected===d.date}"><b>${d.day}</b>${today?'<em>今天</em>':''}${type?`<span class="calendar-dot ${type.color}"></span><small>${today&&!o.checked?'點我查看':esc(type.short)}</small>`:'<small>—</small>'}</button>`;}).join('');
 return`<div class="calendar-layout"><section class="calendar-month"><header><div><small>ENT / MONTHLY SCHEDULE</small><h2 id="modalTitle">${year} 年 ${month+1} 月</h2><span class="calendar-now">現在 <b id="calendarNow">${esc(nowLabel)}</b></span></div><nav aria-label="切換月份"><button id="calendarPrev" aria-label="上個月">‹</button><button id="calendarToday">回本月</button><button id="calendarNext" aria-label="下個月">›</button></nav></header><div class="calendar-week">${'日一二三四五六'.split('').map(d=>`<span>${d}</span>`).join('')}</div><div class="calendar-grid">${days}</div><footer><span>● 鼻耳</span><span>● 喉</span><span>● 頭頸</span><span>● paper reading</span></footer></section><aside class="calendar-agenda">${selected?`<span class="modal-tag">${esc(selected)}${isToday?' · 今天':''}</span><h3>${entry?'07:30　'+esc(entry.label):'今日無晨會'}</h3>${entry?`<p>地點：7F 討論室<br>07:30 開始，請準時到場。</p>${isToday?`<div class="calendar-paper"><small>今日報告 paper</small><strong>${esc(conferencePaper(o).title)}</strong><span>科內虛構研究</span></div><p class="calendar-attendance">${o.stage==='missed'?'晨會已結束，缺席紀錄保留。':o.attendance==='late'?'你已遲到；請先接上報告。':o.stage==='done'?'✓ 今日報告已完成。':'先到討論室，再開始報告。'}</p>`:''}`:'<p>可以到護理站列印 patient list，直接查房。</p>'}${isToday?`<button id="calendarContinue" class="primary-button">${entry&&!['done','missed'].includes(o.stage)?'前往討論室':calendarReturnLabel(o)} →</button>`:'<p class="small-note">點選標有「今天」的日期，確認當日工作。</p>'}`:'<div class="calendar-empty"><span>▦</span><h3>先點選「今天」</h3><p>確認今日有沒有晨會，再決定先去討論室或查房。</p></div>'}<button id="calendarClose" class="text-button">收起行事曆</button></aside></div>`;
}
function calendarReturnLabel(o){return o.stage==='missed'?'回到病房工作':o.stage==='done'&&o.conference?'回到目前工作':'開始查房';}
export function paperHeading(o){const p=conferencePaper(o);return`<span class="modal-tag">07:30 · ${esc(conferenceType(o).label)}</span><h2 id="modalTitle">${esc(p.title)}</h2><p class="paper-subtitle">${esc(p.subtitle)}</p><div class="paper-meta"><span>報告：ENT R</span><span>科內虛構 paper</span><span>${o.attendance==='late'?'遲到紀錄已保留':'7F 討論室'}</span></div>`;}
export function paperSlideHTML(o){const p=conferencePaper(o),s=p.slides[o.slide];return`${paperHeading(o)}<article class="paper-slide"><header><span>${String(o.slide+1).padStart(2,'0')} / ${p.slides.length}</span><b>${esc(s.tag)}</b></header><h3>${esc(s.title)}</h3><p>${esc(s.text)}</p>${s.bars?`<div class="paper-chart" aria-label="虛構研究示意圖">${s.bars.map(([label,value])=>`<div><span>${esc(label)}</span><i><b style="width:${value}%"></b></i></div>`).join('')}</div>`:''}<small>本頁內容與圖表皆為科內娛樂創作。</small></article><div class="paper-actions"><button id="paperPrevious" class="secondary-button" ${o.slide===0?'disabled':''}>← 上一頁</button><button id="paperNext" class="primary-button">${o.slide===p.slides.length-1?'報告完畢，回答主治提問':'下一頁'} →</button></div><button id="conferenceLater" class="text-button">先離開，報告進度保留</button>`;}
